Section F2.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x5 x7 x8 x10 x11 x16 x17 x18 x19 x20 x22 x26 x27 x29 x30 x31 : word).
  Variables (m : fmem) (DT SY cnt sym0 nb : Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HJS : length js = length syms.
  Hypothesis HSYR : forall i v, nth i syms None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 2 * Z.of_nat ncells <= 2^64.
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis HSP : DT + 4 + 2 * Z.of_nat ncells <= SP /\ SP + 64 <= 2^64.
  Hypothesis HSY : 0 < SY /\ SY + zlen js <= 2^64.
  Notation INV m1 cells := (x1f_inv m m1 DT SY js jt syms ncells cells).

  Lemma f2_inner : forall f s cells u (x14 x15 : word) m1 r (x13 x25 : word),
    fill_syms f s cnt sym0 2 nb syms cells u = Ok r ->
    Z.of_nat f = cnt - s + 1 -> 0 <= s < cnt -> 0 <= u -> 0 <= sym0 -> sym0 + cnt <= 512 -> INV m1 cells ->
    (forall m2 cells' (y6 y13 y25 y28 : word),
       r = (cells', u + 2 * (cnt - s)) -> INV m2 cells' ->
       evt psegs POST (MS (mkR x1 sp gp tp x5 y6 x7 x8 (Z_to_bv 64 DT) x10 x11 (Z_to_bv 64 SY) y13 x14 x15 x16 x17 x18 x19
                               x20 (Z_to_bv 64 cnt) x22 (Z_to_bv 64 (SY + sym0 + cnt)) (Z_to_bv 64 nb) y25 x26 x27 y28 x29
                               x30 x31)
                          F (Z_to_bv 64 0x136e0) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 (Z_to_bv 64 (SY + sym0 + s)) x7 x8 (Z_to_bv 64 DT) x10 x11 (Z_to_bv 64 SY) x13
                            x14 x15 x16 x17 x18 x19 x20 (Z_to_bv 64 cnt) x22 (Z_to_bv 64 (SY + sym0 + cnt))
                            (Z_to_bv 64 nb) x25 x26 x27 (Z_to_bv 64 (DT + 7 + 2 * u)) x29 x30 x31)
                       F (Z_to_bv 64 0x13738) fc None m1 (seg_rom psegs)).
